   */
  @TypedRoute.Post(":todoId/toggle")
  public async toggle(
    @MemberAuth()
    member: MemberPayload,
    @TypedParam("todoId")
    todoId: string & tags.Format<"uuid">,
  ): Promise<IPrivateTodoAppTodo> {
    try {
